#!/usr/bin/env node
// Generates the limits, quotas, regions and pricing tables from data/limits.json.
//
//   node scripts/limits/generate.mjs           write snippets/limits/*.mdx and pricing.mdx
//   node scripts/limits/generate.mjs --check   fail if a generated file is stale, the data
//                                              file is invalid, or a docs page states a
//                                              number that disagrees with the data file
//
// No dependencies: Node 20 or later.

import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const DATA_PATH = join(ROOT, 'data', 'limits.json');
const SNIPPET_DIR = join(ROOT, 'snippets', 'limits');
const PAGE_PATH = join(ROOT, 'pricing.mdx');
const CHECK = process.argv.includes('--check');

const HEADER =
  '{/* Generated from data/limits.json by scripts/limits/generate.mjs. Do not edit this file: edit the data file and run `npm run limits:generate`. */}';

// ---------------------------------------------------------------------------
// Data validation

// Sources must be public. Reject code paths, issue trackers, chats and ticket references.
const FORBIDDEN_SOURCE = /github\.com|gitlab\.com|linear\.app|slack\.com|notion\.(so|site)|\.(go|ts|js|py|rs|ya?ml)\b|\bticket|#\d+/i;
const ISSUE_KEY = /\b[A-Z]{2,6}-\d+\b/;

function fail(message) {
  console.error(`limits: ${message}`);
  process.exitCode = 1;
}

function validate(data) {
  const errors = [];
  const entry = (where, obj) => {
    if (!obj || typeof obj !== 'object') {
      errors.push(`${where}: not an object`);
      return;
    }
    if (typeof obj.source !== 'string' || obj.source.trim() === '') errors.push(`${where}: missing "source"`);
    else if (FORBIDDEN_SOURCE.test(obj.source) || ISSUE_KEY.test(obj.source))
      errors.push(`${where}: "source" must name a public docs page, a public blaxel.ai page, or "platform config" (got "${obj.source}")`);
    if (typeof obj.verified !== 'boolean') errors.push(`${where}: "verified" must be true or false`);
  };
  const keys = new Set();
  const unique = (where, key) => {
    if (typeof key !== 'string' || key === '') errors.push(`${where}: missing "key"`);
    else if (keys.has(key)) errors.push(`${where}: duplicate key "${key}"`);
    else keys.add(key);
  };

  if (!/^\d{4}-\d{2}-\d{2}$/.test(data.reviewed ?? '')) errors.push('"reviewed" must be a YYYY-MM-DD date');

  const tiers = data.tiers;
  entry('tiers', tiers);
  const tierCount = tiers?.levels?.length ?? 0;
  if (tierCount === 0) errors.push('tiers.levels is empty');
  tiers?.levels?.forEach((level, i) => {
    if (level.tier !== i) errors.push(`tiers.levels[${i}]: tiers must be listed in order starting at 0`);
    entry(`tiers.levels[${i}]`, level);
  });
  tiers?.quotas?.forEach((quota, i) => {
    const where = `tiers.quotas[${i}] (${quota.key})`;
    unique(where, quota.key);
    entry(where, quota);
    if (!UNITS[quota.unit]) errors.push(`${where}: unknown unit "${quota.unit}"`);
    if (!Array.isArray(quota.values) || quota.values.length !== tierCount)
      errors.push(`${where}: "values" must hold one value per tier (${tierCount})`);
    else if (quota.values.some((v) => v !== null && typeof v !== 'number'))
      errors.push(`${where}: values must be numbers or null`);
    if (quota.values?.includes(null) && !quota.null_label) errors.push(`${where}: null values need a "null_label"`);
  });

  data.limits?.forEach((limit, i) => {
    const where = `limits[${i}] (${limit.key})`;
    unique(where, limit.key);
    entry(where, limit);
    if (!LIMIT_GROUPS[limit.group]) errors.push(`${where}: unknown group "${limit.group}"`);
    if (typeof limit.value !== 'number') errors.push(`${where}: "value" must be a number`);
    if (!UNITS[limit.unit]) errors.push(`${where}: unknown unit "${limit.unit}"`);
  });

  entry('cpu', data.cpu);
  data.cpu?.rows?.forEach((row, i) => {
    if (typeof row.memory_mb !== 'number' || typeof row.vcpus !== 'number') errors.push(`cpu.rows[${i}]: needs memory_mb and vcpus`);
  });

  data.regions?.items?.forEach((region, i) => {
    unique(`regions.items[${i}]`, region.key);
    entry(`regions.items[${i}] (${region.key})`, region);
  });

  data.pricing?.items?.forEach((price, i) => {
    const where = `pricing.items[${i}] (${price.key})`;
    unique(where, price.key);
    entry(where, price);
    if (typeof price.rate !== 'string' || price.rate === '') errors.push(`${where}: "rate" must be the rate as published, for example "$0.12"`);
  });

  return errors;
}

// ---------------------------------------------------------------------------
// Formatting

const UNITS = {
  count: (v) => v.toLocaleString('en-US'),
  bytes: (v) => formatBytes(v),
  MB: (v) => formatMegabytes(v),
  seconds: (v) => formatSeconds(v),
  minutes: (v) => formatSeconds(v * 60),
  days: (v) => plural(v, 'day'),
  usd: (v) => `$${v.toLocaleString('en-US')}`,
};

function plural(n, word) {
  return `${n.toLocaleString('en-US')} ${word}${n === 1 ? '' : 's'}`;
}

function trim(n) {
  return Number.isInteger(n) ? n.toLocaleString('en-US') : String(Number(n.toFixed(2)));
}

// Memory and storage quotas are configured in MB of 1,024 KB, and shown in GB and TB of 1,024.
function formatMegabytes(mb) {
  if (mb >= 1024 * 1024) return `${trim(mb / (1024 * 1024))} TB`;
  if (mb >= 1024) return `${trim(mb / 1024)} GB`;
  return `${trim(mb)} MB`;
}

function formatBytes(bytes) {
  const mib = bytes / (1024 * 1024);
  if (bytes >= 1024 * 1024 && Number.isInteger(mib)) return `${trim(mib)} MiB (${bytes.toLocaleString('en-US')} bytes)`;
  const kib = bytes / 1024;
  if (bytes >= 1024 && Number.isInteger(kib)) return `${trim(kib)} KiB (${bytes.toLocaleString('en-US')} bytes)`;
  return `${bytes.toLocaleString('en-US')} bytes`;
}

function formatSeconds(s) {
  if (s % 86400 === 0 && s >= 172800) return plural(s / 86400, 'day');
  if (s % 3600 === 0) return plural(s / 3600, 'hour');
  if (s % 60 === 0) return plural(s / 60, 'minute');
  return plural(s, 'second');
}

function formatValue(value, unit, nullLabel) {
  if (value === null || value === undefined) return nullLabel ?? 'None';
  return UNITS[unit](value);
}

// Escape characters that MDX or Markdown tables would interpret.
function cell(text) {
  return String(text).replace(/\|/g, '\\|').replace(/[{}<>]/g, (c) => `\\${c}`);
}

function table(headers, rows) {
  return [
    `| ${headers.map(cell).join(' | ')} |`,
    `| ${headers.map(() => '---').join(' | ')} |`,
    ...rows.map((row) => `| ${row.map(cell).join(' | ')} |`),
  ].join('\n');
}

// ---------------------------------------------------------------------------
// Tables

const TIER_TABLES = {
  'tier-sandboxes': ['top_up', 'sandboxes', 'memory_per_instance', 'sandbox_max_ttl', 'terminated_retention'],
  'tier-sandbox-features': ['previews', 'snapshots_total', 'snapshots_per_sandbox', 'schedules_per_sandbox'],
  'tier-storage': ['volumes', 'volume_max_size', 'volume_total_size', 'volume_templates', 'image_storage'],
  'tier-workloads': ['agents', 'mcp_servers', 'jobs', 'job_concurrent_tasks', 'job_memory_total', 'runtime_timeout', 'ephemeral_volume_max_size'],
  'tier-account': ['workspaces', 'workspace_users', 'custom_domains', 'metrics_retention'],
};

const LIMIT_GROUPS = {
  requests: 'Request and payload sizes',
  rate: 'Rate and concurrency',
  sandbox: 'Sandbox settings',
};

function tierTable(data, columns) {
  const quotas = new Map(data.tiers.quotas.map((q) => [q.key, q]));
  const headers = ['Tier'];
  for (const key of columns) {
    if (key === 'top_up') headers.push('30-day top-ups');
    else if (!quotas.has(key)) throw new Error(`tier table column "${key}" is not in tiers.quotas`);
    else headers.push(quotas.get(key).label);
  }
  const rows = data.tiers.levels.map((level, i) => [
    String(level.tier),
    ...columns.map((key) => {
      if (key === 'top_up') return level.requirement;
      const q = quotas.get(key);
      return formatValue(q.values[i], q.unit, q.null_label);
    }),
  ]);
  return table(headers, rows);
}

function limitsTable(limits, { withGroup = false } = {}) {
  const headers = [...(withGroup ? ['Area'] : []), 'Limit', 'Value', 'When exceeded'];
  const rows = limits.map((l) => [
    ...(withGroup ? [LIMIT_GROUPS[l.group]] : []),
    l.label,
    l.display ?? formatValue(l.value, l.unit),
    l.on_exceed,
  ]);
  return table(headers, rows);
}

// Each row covers the memory sizes above the previous row, up to its own size. The last
// row also covers every larger size.
function cpuTable(data) {
  const rows = data.cpu.rows;
  return table(
    ['Memory', 'vCPUs'],
    rows.map((r, i) => [
      i === rows.length - 1 && i > 0 ? `More than ${formatMegabytes(rows[i - 1].memory_mb)}` : `Up to ${formatMegabytes(r.memory_mb)}`,
      String(r.vcpus),
    ]),
  );
}

function regionsTable(data) {
  return table(
    ['Region code', 'Location', 'Country'],
    data.regions.items.map((r) => [`\`${r.key}\``, r.location, r.country]),
  );
}

function pricingTable(data, products) {
  const items = data.pricing.items.filter((p) => !products || products.includes(p.product));
  return table(
    ['Product', 'Item', 'Rate'],
    items.map((p) => [p.product, p.item, p.unit ? `${p.rate} per ${p.unit}` : p.rate]),
  );
}

const byGroup = (data, group) => data.limits.filter((l) => l.group === group);
const byKeys = (data, keys) =>
  keys.map((k) => {
    const l = data.limits.find((x) => x.key === k);
    if (!l) throw new Error(`limit "${k}" is not in data/limits.json`);
    return l;
  });

function snippet(body) {
  return `${HEADER}\n\n${body.trim()}\n`;
}

function buildSnippets(data) {
  const out = {};
  for (const [name, columns] of Object.entries(TIER_TABLES)) out[`${name}.mdx`] = snippet(tierTable(data, columns));
  out['cpu-per-memory.mdx'] = snippet(cpuTable(data));
  out['request-limits.mdx'] = snippet(limitsTable(byGroup(data, 'requests')));
  out['upload-limits.mdx'] = snippet(limitsTable(byKeys(data, data.snippets.upload_limits)));
  out['rate-limits.mdx'] = snippet(limitsTable(byGroup(data, 'rate')));
  out['sandbox-limits.mdx'] = snippet(limitsTable(byGroup(data, 'sandbox')));
  out['regions.mdx'] = snippet(regionsTable(data));
  out['pricing.mdx'] = snippet(pricingTable(data));
  return out;
}

// The agent-readable page: every table inline as plain Markdown, so the page source,
// the rendered page and its .md export all carry the numbers.
function buildPage(data) {
  const t = data.tiers;
  const sections = [
    `---
title: 'Pricing, quotas and limits'
sidebarTitle: 'Pricing and limits'
description: 'Blaxel prices, quota tiers, request size limits, rate limits and regions in plain tables, generated from one data file.'
---

${HEADER}

This page lists Blaxel prices, the quotas of each tier, request size and rate limits, and regions in one place. Values were last reviewed on ${data.reviewed}. Your account can have higher limits than its tier: the [Quotas page of the Blaxel Console](https://app.blaxel.ai/account/quotas) shows the values that apply to you.`,

    `## Pricing

Compute is billed by the second for the memory you allocate, and CPU scales with memory. The rates below are the pay-as-you-go rates published on [blaxel.ai/pricing](https://blaxel.ai/pricing).

${pricingTable(data)}

A sandbox in standby doesn't use compute: you pay only for its snapshot and volume storage. See [sandbox lifecycle](/Sandboxes/Overview#sandbox-lifecycle).`,

    `## Quota tiers

Your tier rises with the top-ups you made in the past 30 days, and each tier includes the quotas of the tiers below it. Promotional credits don't count toward a tier. Quotas apply to your whole account, across all its workspaces. See [usage and quotas](/Security/Quotas) for how tiers are calculated and how to request an increase.

### Sandboxes

${tierTable(data, TIER_TABLES['tier-sandboxes'])}

${tierTable(data, TIER_TABLES['tier-sandbox-features'])}

### Volumes and images

${tierTable(data, TIER_TABLES['tier-storage'])}

### Agents, MCP servers and jobs

${tierTable(data, TIER_TABLES['tier-workloads'])}

### Account

${tierTable(data, TIER_TABLES['tier-account'])}`,

    `## Sandbox resources

By default, Blaxel allocates vCPUs from the memory you set.

${cpuTable(data)}

${limitsTable(byGroup(data, 'sandbox'))}`,

    `## Request and payload sizes

${limitsTable(byGroup(data, 'requests'))}

See [write binary file](/Sandboxes/Filesystem#write-binary-file) for multipart uploads, and [error codes](/troubleshooting/error-codes) for the structured errors.`,

    `## Rate and concurrency limits

${limitsTable(byGroup(data, 'rate'))}`,

    `## Regions

${regionsTable(data)}

Set \`region\` to \`auto\` to let Blaxel pick the closest region. To allowlist Blaxel traffic, retrieve the [public IP addresses](/Infrastructure/Regions#public-ip-addresses) of each region from the API: they are not listed here because they change as the platform scales.`,

    `<CardGroup cols={2}>
  <Card title="Usage and quotas" icon="gauge" href="/Security/Quotas">
    Check your tier and request a quota increase.
  </Card>
  <Card title="Regions" icon="earth-americas" href="/Infrastructure/Regions">
    Choose where your resources run.
  </Card>
</CardGroup>`,
  ];
  return `${sections.join('\n\n')}\n`;
}

// ---------------------------------------------------------------------------
// Scan docs pages for hard-coded numbers that disagree with the data file

const SCAN_SKIP_DIRS = new Set(['api-reference', 'cli-reference', 'sdk-reference', 'node_modules', '.git', 'snippets']);
const SCAN_SKIP_FILES = new Set(['changelog.mdx', 'pricing.mdx']);

function listPages(dir = ROOT, out = []) {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) {
      if (!SCAN_SKIP_DIRS.has(name) && !name.startsWith('.')) listPages(full, out);
    } else if (name.endsWith('.mdx') && !(dir === ROOT && SCAN_SKIP_FILES.has(name))) {
      out.push(full);
    }
  }
  return out;
}

const SIZE_UNITS = { kib: 1024, kb: 1024, mib: 1024 ** 2, mb: 1024 ** 2, gib: 1024 ** 3, gb: 1024 ** 3, tib: 1024 ** 4, tb: 1024 ** 4 };
const SIZE_RE = /(\d+(?:\.\d+)?)\s?(KiB|KB|MiB|MB|GiB|GB|TiB|TB)\b/g;
const DURATION_RE = /`?(\d+)\s?(s|m|h|d|seconds?|minutes?|hours?|days?)\b`?/g;
const DURATION_UNITS = { s: 1, second: 1, seconds: 1, m: 60, minute: 60, minutes: 60, h: 3600, hour: 3600, hours: 3600, d: 86400, day: 86400, days: 86400 };

function sizes(text) {
  return [...text.matchAll(SIZE_RE)].map((m) => ({ text: m[0], bytes: Math.round(Number(m[1]) * SIZE_UNITS[m[2].toLowerCase()]) }));
}

function durations(text) {
  return [...text.matchAll(DURATION_RE)].map((m) => ({
    text: m[0].replace(/`/g, ''),
    seconds: Number(m[1]) * DURATION_UNITS[m[2]],
    index: m.index,
    end: m.index + m[0].length,
  }));
}

function limitBytes(limit) {
  if (limit.unit === 'bytes') return limit.value;
  if (limit.unit === 'MB') return limit.value * 1024 ** 2;
  throw new Error(`limit ${limit.key} is not a size`);
}

function limitSeconds(limit) {
  if (limit.unit === 'seconds') return limit.value;
  if (limit.unit === 'minutes') return limit.value * 60;
  throw new Error(`limit ${limit.key} is not a duration`);
}

// Each rule matches sentences about one limit and checks the numbers in them.
// Start small: only rules that can match without false positives belong here.
export function scanRules(data) {
  const limit = (key) => byKeys(data, [key])[0];
  const quota = (key) => data.tiers.quotas.find((q) => q.key === key);
  const quotaBytes = (key) => quota(key).values.filter((v) => v !== null).map((mb) => mb * 1024 ** 2);
  const sizeRule = (id, keys, extraBytes, what, test) => {
    const allowed = new Set([...keys.map((k) => limitBytes(limit(k))), ...extraBytes]);
    return {
      id,
      test,
      check: (s) => sizes(s).filter((x) => !allowed.has(x.bytes)).map((x) => `${x.text} is not ${what} in data/limits.json`),
    };
  };
  const volumeQuotas = ['volume_max_size', 'volume_total_size', 'ephemeral_volume_max_size'];
  return [
    sizeRule('upload-limit', data.scan.upload_413, [], `a 413 limit (${data.scan.upload_413.join(', ')})`, (s) => /\b413\b/.test(s)),
    sizeRule('multipart-chunk', data.scan.multipart, [], `the multipart part size (${data.scan.multipart.join(', ')})`, (s) => /multipart/i.test(s) && /\b(split|chunk|part)s?\b/i.test(s)),
    sizeRule(
      'volume-max-size',
      [],
      volumeQuotas.flatMap(quotaBytes),
      `a volume size quota (${volumeQuotas.join(', ')})`,
      (s) => /\bvolumes?\b/i.test(s) && /\b(max(imum)?|up to|at most|limit|exceeds?)\b/i.test(s) && !/\bat least\b/i.test(s),
    ),
    {
      id: 'ttl-minimum',
      test: (s) => /\bttl/i.test(s) && /\b(minimum|at least|too short)\b/i.test(s),
      // A number is the minimum of the policy named last before it, or of any
      // policy when none is named yet. In "ttl 1m is too short", 1m is a value
      // the API rejects, not a minimum.
      check: (s) => {
        const keys = data.scan.ttl_minimums;
        const policies = [...s.matchAll(/\bttl(?:-max-age|-idle)?\b/gi)];
        return durations(s)
          .filter((d) => !/^\s*is too short\b/.test(s.slice(d.end)))
          .flatMap((d) => {
            const policy = policies.filter((p) => p.index < d.index).at(-1)?.[0].toLowerCase();
            const expected = policy ? [keys[policy]] : [...new Set(Object.values(keys))];
            if (expected.some((k) => limitSeconds(limit(k)) === d.seconds)) return [];
            return [`${d.text} is not the ${policy ? `\`${policy}\`` : 'TTL'} minimum in data/limits.json (${expected.join(', ')})`];
          });
      },
    },
    {
      id: 'create-concurrency',
      test: (s) => /\bsandbox/i.test(s) && /\bcreat/i.test(s) && /\b(concurrent|in flight|at once|at the same time)\b/i.test(s),
      check: (s) => {
        const expected = limit(data.scan.create_concurrency).value;
        return [...s.matchAll(/\b(\d[\d,]*)\b(?!\s?(?:%|ms|s\b|MB|GB|MiB|GiB))/g)]
          .map((m) => Number(m[1].replace(/,/g, '')))
          .filter((n) => n >= 10 && n !== expected && ![409, 429, 500, 502, 503, 504].includes(n))
          .map((n) => `${n} does not match the sandbox creation limit (${expected}) in data/limits.json`);
      },
    },
    {
      id: 'cpu-per-memory',
      test: (s) => /\bGB\b/.test(s) && /\b(v?CPU|cores?)\b/i.test(s),
      check: (s) => {
        const vcpus = new Map(data.cpu.rows.map((r) => [r.memory_mb, r.vcpus]));
        const found = [];
        for (const m of s.matchAll(/(\d+)\s?GB(?: of)? memory\b[^.\n]{0,40}?\b(\d+)\s(?:v?CPUs?|CPU cores?|cores?)/gi)) {
          const expected = vcpus.get(Number(m[1]) * 1024);
          if (expected !== undefined && expected !== Number(m[2]))
            found.push(`${m[1]} GB gets ${expected} vCPUs in data/limits.json, the page says ${m[2]}`);
        }
        return found;
      },
    },
  ];
}

// Split a page into sentences with line numbers, skipping frontmatter, imports and code.
function sentences(text) {
  const out = [];
  let inFence = false;
  let inFrontmatter = false;
  text.split('\n').forEach((line, i) => {
    if (i === 0 && line.trim() === '---') {
      inFrontmatter = true;
      return;
    }
    if (inFrontmatter) {
      if (line.trim() === '---') inFrontmatter = false;
      return;
    }
    if (/^\s*(```|~~~)/.test(line)) {
      inFence = !inFence;
      return;
    }
    if (inFence || /^\s*(import|export) /.test(line)) return;
    const prose = line.replace(/`([^`]*)`/g, '$1');
    for (const part of prose.split(/(?<=[.!?])\s+(?=[A-Z`*_(])/)) out.push({ line: i + 1, text: part });
  });
  return out;
}

function scan(data) {
  const rules = scanRules(data);
  const findings = [];
  for (const file of listPages()) {
    const text = readFileSync(file, 'utf8');
    for (const s of sentences(text)) {
      for (const rule of rules) {
        if (!rule.test(s.text)) continue;
        for (const message of rule.check(s.text)) findings.push(`${relative(ROOT, file).split(sep).join('/')}:${s.line}: [${rule.id}] ${message}`);
      }
    }
  }
  return findings;
}

// ---------------------------------------------------------------------------

function main() {
  let data;
  try {
    data = JSON.parse(readFileSync(DATA_PATH, 'utf8'));
  } catch (err) {
    fail(`cannot read ${relative(ROOT, DATA_PATH)}: ${err.message}`);
    return;
  }

  const errors = validate(data);
  if (errors.length) {
    errors.forEach((e) => fail(`data/limits.json: ${e}`));
    return;
  }

  const files = Object.fromEntries(Object.entries(buildSnippets(data)).map(([name, body]) => [join(SNIPPET_DIR, name), body]));
  files[PAGE_PATH] = buildPage(data);

  const stale = Object.entries(files).filter(([path, body]) => !existsSync(path) || readFileSync(path, 'utf8') !== body);
  const orphans = existsSync(SNIPPET_DIR)
    ? readdirSync(SNIPPET_DIR).map((n) => join(SNIPPET_DIR, n)).filter((p) => !(p in files))
    : [];

  if (CHECK) {
    stale.forEach(([path]) => fail(`${relative(ROOT, path)} is out of date: run \`npm run limits:generate\``));
    orphans.forEach((path) => fail(`${relative(ROOT, path)} is no longer generated: delete it or run \`npm run limits:generate\``));
  } else {
    mkdirSync(SNIPPET_DIR, { recursive: true });
    for (const [path, body] of stale) {
      writeFileSync(path, body);
      console.log(`wrote ${relative(ROOT, path)}`);
    }
    for (const path of orphans) {
      rmSync(path);
      console.log(`removed ${relative(ROOT, path)}`);
    }
    if (!stale.length && !orphans.length) console.log('generated files are up to date');
  }

  const findings = scan(data);
  findings.forEach((f) => (CHECK ? fail(f) : console.warn(`warning: ${f}`)));
  if (CHECK && process.exitCode !== 1) console.log(`limits: ${Object.keys(files).length} generated files up to date, no conflicting numbers in docs pages`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
